/**
 * Picks, among a set of candidates tied for fewest votes in the current
 * round, the one to eliminate: the one with the fewest votes across the
 * earliest round that distinguishes them, restarting the comparison from
 * the first round among the survivors each time a round distinguishes some
 * of them, and falling back to the name that sorts last by code point when
 * no round ever distinguishes them.
 */
function breakTie(tied, history) {
  let group = tied.slice()
  for (;;) {
    let narrowed = false
    for (const roundVotes of history) {
      const values = group.map((name) => roundVotes[name])
      const min = Math.min(...values)
      if (!values.every((v) => v === min)) {
        group = group.filter((name) => roundVotes[name] === min)
        narrowed = true
        break
      }
    }
    if (!narrowed) break
    if (group.length === 1) break
  }
  if (group.length === 1) return group[0]
  return group.reduce((a, b) => (a > b ? a : b))
}

/**
 * Runs the count, returning `{ rounds, winner }`. `rounds` is a list of
 * `{ votes, order, exhausted, eliminated }`, one per round counted, where
 * `votes` maps every candidate continuing that round to its count, `order`
 * lists those candidates by descending votes then ascending name, and
 * `eliminated` is the candidate removed after the round or `null` for the
 * round that ended the election. `winner` is the winning name or `null`.
 */
export function runElection(candidates, ballots) {
  let continuing = new Set(candidates)
  const history = []
  const rounds = []
  let winner = null

  for (;;) {
    const votes = {}
    for (const name of continuing) votes[name] = 0
    let exhausted = 0
    let activeTotal = 0

    for (const ballot of ballots) {
      const choice = ballot.prefs.find((name) => continuing.has(name))
      if (choice !== undefined) {
        votes[choice] += ballot.count
        activeTotal += ballot.count
      } else {
        exhausted += ballot.count
      }
    }

    history.push(votes)
    const order = [...continuing].sort((a, b) => votes[b] - votes[a] || (a < b ? -1 : 1))
    const round = { votes, order, exhausted, eliminated: null }
    rounds.push(round)

    if (activeTotal === 0) break

    const majority = order.find((name) => votes[name] * 2 > activeTotal)
    if (majority !== undefined) {
      winner = majority
      break
    }

    const min = Math.min(...[...continuing].map((name) => votes[name]))
    const tied = [...continuing].filter((name) => votes[name] === min)
    const eliminated = tied.length === 1 ? tied[0] : breakTie(tied, history)
    round.eliminated = eliminated
    continuing.delete(eliminated)
  }

